def detect_type(filepath):
    sigs = {b'%PDF': 'pdf', b'PK\x03\x04': 'docx', b'\x89PNG': 'png', b'\xff\xd8\xff': 'jpg'}
    with open(filepath, 'rb') as f:
        h = f.read(4)
    for sig, t in sigs.items():
        if h.startswith(sig): return t
    return 'unknown'

